  XW += x[26] * 42.037640;                      /*CH2CO */
  XW += x[27] * 42.037640;                      /*HCCOH */
  XW += x[28] * 43.045610;                      /*CH2HCO */
  XW += x[29] * 43.045610;                      /*CH3CO */
