  YOW += y[45] * imw[45];                        /*OCH2OCHO */
  YOW += y[46] * imw[46];                        /*HOCH2OCO */
  YOW += y[47] * imw[47];                        /*HOC2H4O2 */
  YOW += y[48] * imw[48];                        /*CH3OCH2O2 */
