  YOW += y[87] * imw[87];                        /*FC6H6 */
  YOW += y[88] * imw[88];                        /*C6H6 */
  YOW += y[89] * imw[89];                        /*C6H5 */
  YOW += y[90] * imw[90];                        /*C2H3CHO */
  YOW += y[91] * imw[91];                        /*C5H6 */
  YOW += y[92] * imw[92];                        /*C2H3CO */
  YOW += y[93] * imw[93];                        /*C4H */
  YOW += y[94] * imw[94];                        /*H2C4O */
  YOW += y[95] * imw[95];                        /*C6H2 */
  YOW += y[96] * imw[96];                        /*C6H3 */
  YOW += y[97] * imw[97];                        /*l-C6H4 */
  YOW += y[98] * imw[98];                        /*o-C6H4 */
  YOW += y[99] * imw[99];                        /*CH3CHCHCO */
  YOW += y[100] * imw[100];                      /*CH2CHCHCHO */
  YOW += y[101] * imw[101];                      /*C5H5 */
  YOW += y[102] * imw[102];                      /*C6H5O */
