  XW += x[41] * 59.045010;   /*CH3OCO */
  XW += x[42] * 60.052980;   /*CH3OCHO */
  XW += x[43] * 61.060950;   /*CH3OCH2O */
  XW += x[44] * 62.068920;   /*CH3OCH2OH */
  XW += x[45] * 75.044410;   /*OCH2OCHO */
  XW += x[46] * 75.044410;   /*HOCH2OCO */
  XW += x[47] * 77.060350;   /*HOC2H4O2 */
  XW += x[48] * 77.060350;   /*CH3OCH2O2 */
  XW += x[49] * 77.060350;   /*CH2OCH2O2H */
  XW += x[50] * 78.068320;   /*CH3OCH2O2H */
  XW += x[51] * 92.051780;   /*HO2CH2OCHO */
  XW += x[52] * 109.059150;  /*O2CH2OCH2O2H */
  XW += x[53] * 39.948000;   /*AR */
  XW += x[54] * 4.002600;    /*HE */
  XW += x[55] * 12.011150;   /*C */
  XW += x[56] * 13.019120;   /*CH */
  XW += x[57] * 30.026490;   /*HCOH */
  XW += x[58] * 40.021700;   /*C2O */
  XW += x[59] * 47.033860;   /*CH3O2 */
  XW += x[60] * 48.041830;   /*CH3O2H */
  XW += x[61] * 38.049390;   /*C3H2 */
  XW += x[62] * 38.049390;   /*C3H2SING */
  XW += x[63] * 38.049390;   /*c-C3H2 */
