  W += c[26] * 42.037640;   /*CH2CO */
  W += c[27] * 42.037640;   /*HCCOH */
  W += c[28] * 43.045610;   /*CH2HCO */
  W += c[29] * 43.045610;   /*CH3CO */
  W += c[30] * 44.009950;   /*CO2 */
  W += c[31] * 44.053580;   /*CH3HCO */
  W += c[32] * 45.017920;   /*OCHO */
  W += c[33] * 45.061550;   /*CH3CHOH */
  W += c[34] * 45.061550;   /*C2H4OH */
  W += c[35] * 45.061550;   /*CH3CH2O */
  W += c[36] * 45.061550;   /*CH3OCH2 */
  W += c[37] * 46.025890;   /*HOCHO */
  W += c[38] * 46.069520;   /*CH3OCH3 */
  W += c[39] * 46.069520;   /*C2H5OH */
  W += c[40] * 47.033860;   /*HOCH2O */
  W += c[41] * 59.045010;   /*CH3OCO */
  W += c[42] * 60.052980;   /*CH3OCHO */
  W += c[43] * 61.060950;   /*CH3OCH2O */
  W += c[44] * 62.068920;   /*CH3OCH2OH */
  W += c[45] * 75.044410;   /*OCH2OCHO */
  W += c[46] * 75.044410;   /*HOCH2OCO */
  W += c[47] * 77.060350;   /*HOC2H4O2 */
  W += c[48] * 77.060350;   /*CH3OCH2O2 */
