  W += c[90] * 56.064730;   /*C2H3CHO */
  W += c[91] * 66.103570;   /*C5H6 */
  W += c[92] * 55.056760;   /*C2H3CO */
  W += c[93] * 49.052570;   /*C4H */
  W += c[94] * 66.059940;   /*H2C4O */
  W += c[95] * 74.082840;   /*C6H2 */
  W += c[96] * 75.090810;   /*C6H3 */
  W += c[97] * 76.098780;   /*l-C6H4 */
  W += c[98] * 76.098780;   /*o-C6H4 */
  W += c[99] * 69.083850;   /*CH3CHCHCO */
