  XW += x[111] * 59.045010;  /*CH2OCHO */
  XW += x[112] * 45.017920;  /*HOCO */
  XW += x[113] * 45.061550;  /*C2H5O */
  XW += x[114] * 61.060950;  /*C2H5O2 */
  XW += x[115] * 62.068920;  /*C2H5O2H */
  XW += x[116] * 61.060950;  /*C2H4O2H */
  XW += x[117] * 57.072700;  /*C2H5CO */
  XW += x[118] * 58.080670;  /*C2H5CHO */
  XW += x[119] * 59.045010;  /*CH3CO2 */
  XW += x[120] * 75.044410;  /*CH3CO3 */
  XW += x[121] * 76.052380;  /*CH3CO3H */
  XW += x[122] * 63.033260;  /*OCH2O2H */
  XW += x[123] * 63.033260;  /*HOCH2O2 */
