  F = redP / (1.0 + redP);
  logPred = log10(redP);
  logFcent =
    log10((0.57) * exp(-tc[1] * 1e+30) + 0.43 * exp(-tc[1] * 1e-30) + 0.0);
  troe_c = -0.4 - 0.67 * logFcent;
  troe_n = 0.75 - 1.27 * logFcent;
  troe = (troe_c + logPred) / (troe_n - 0.14 * (troe_c + logPred));
  F_troe = pow(10, logFcent / (1.0 + troe * troe));
  Corr = F * F_troe;
  qf[1] *= Corr * k_f;
