  redP = Corr / k_f * 1e-12 * 4.436e+23 *
         exp(-2.637 * tc[0] - 0.50321666580472 * (4081.9) * invT);
  Corr = redP / (1. + redP);
  qf[36] *= Corr * k_f;
  qr[36] *= Corr * k_f * exp(-(g_RT[5] + g_RT[12] - g_RT[30])) * (refC);
