  qr[79] *= k_f * exp(-(-g_RT[7] + g_RT[12] + g_RT[23] - g_RT[30]));
  // (30):  CO + OH <=> CO2 + H
  k_f = 0.07046 * exp((2.053) * tc[0] - (-138.988443095264) * invT);
  qf[80] *= k_f;
  qr[80] *= k_f * exp(-(-g_RT[0] + g_RT[7] + g_RT[12] - g_RT[30]));
  // (31):  CO + OH <=> CO2 + H
  k_f = 5757000 * exp((-0.664) * tc[0] - (167.017611380586) * invT);
  qf[81] *= k_f;
