  k_f = 18.5 * exp((1.51) * tc[0] - (-484.09443250414) * invT);
  qf[833] *= k_f;
  qr[833] *=
    k_f * exp(-(g_RT[7] - g_RT[7] - g_RT[8] - g_RT[12] + g_RT[37])) * (refCinv);
