  qr[856] *= k_f * exp(-(-g_RT[41] + g_RT[42] + g_RT[59] - g_RT[60]));
  // (857):  CH3OCHO + CH3O2 <=> CH2OCHO + CH3O2H
  k_f = 0.0238 * exp((2.55) * tc[0] - (8298.04281911983) * invT);
