  // (869):  HOCO + H <=> CO2 + H2
  k_f = 310000000000 * exp((-1.3475) * tc[0] - (278.96973267216) * invT);
  qf[869] *= k_f;
  qr[869] *= k_f * exp(-(g_RT[0] - g_RT[1] - g_RT[30] + g_RT[112]));
  // (870):  HOCO + H <=> CO + H2O
  k_f = 6000000000 * exp((-0.525) * tc[0] - (1068.8840294858) * invT);
  qf[870] *= k_f;
  qr[870] *= k_f * exp(-(g_RT[0] - g_RT[8] - g_RT[12] + g_RT[112]));
  // (871):  HOCO + O <=> CO2 + OH
  k_f = 9000000;
