  qr[871] *= k_f * exp(-(g_RT[5] - g_RT[7] - g_RT[30] + g_RT[112]));
  // (872):  CO + H2O2 <=> HOCO + OH
  k_f = 0.036 * exp((2.5) * tc[0] - (14422.4352116962) * invT);
