  // (876):  HOCHO + H <=> OCHO + H2
  k_f = 0.42 * exp((2.255) * tc[0] - (7091.23062405361) * invT);
  qf[876] *= k_f;
  qr[876] *= k_f * exp(-(g_RT[0] - g_RT[1] - g_RT[32] + g_RT[37]));
  // (877):  HOCO + OH <=> CO2 + H2O
  k_f = 4600000 * exp(-(-44.995118172929) * invT);
  qf[877] *= k_f;
  qr[877] *= k_f * exp(-(g_RT[7] - g_RT[8] - g_RT[30] + g_RT[112]));
  // (878):  HOCO + OH <=> CO2 + H2O
  k_f = 9.5 * exp((2) * tc[0] - (-44.995118172929) * invT);
  qf[878] *= k_f;
  qr[878] *= k_f * exp(-(g_RT[7] - g_RT[8] - g_RT[30] + g_RT[112]));
  // (879):  HOCO + HO2 <=> HOCHO + O2
  k_f = 400000;
  qf[879] *= k_f;
  qr[879] *= k_f * exp(-(-g_RT[21] + g_RT[23] - g_RT[37] + g_RT[112]));
  // (880):  HOCHO + O2 <=> OCHO + HO2
  k_f = 30000000 * exp(-(31696.5610240411) * invT);
  qf[880] *= k_f;
